command:
// ==========================================
// LUNAS WIRKUNG: NURTIS SCHMEICHELN (NURTI)
// - genau 1 menschliches Ziel
// - Dauer: QS Minuten
// - Willenskraft: −2 × QS
// - Ziel und Wirkender erhalten verknüpfte Effekte
// - gespeichertes Ziel | GM-Button | Framework-Effektanlage
// ==========================================
(async function () {
const macroUuid = this?.uuid || game.macros.getName("Nurtis Schmeicheln")?.uuid || null;

// +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++++++
const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
const frameworkFehlt =
    !globalThis.DSK?.Effekt?.Anwenden || !globalThis.DSK?.EffektEnde?.Register ||
    !globalThis.DSK?.QS?.Ermitteln || !globalThis.DSK?.Token?.Finde ||
    !globalThis.DSK?.Target?.Merken || !globalThis.DSK?.Target?.Finden ||
    !globalThis.DSK?.Target?.Actor || !globalThis.DSK?.Wesen?.match ||
    !globalThis.DSK?.GMAnfrage?.Speichern || !globalThis.DSK?.GMAnfrage?.Finden ||
    !globalThis.DSK?.GMAnfrage?.Lesen || !globalThis.DSK?.GMAnfrage?.Loeschen ||
    !globalThis.DSK?.GabenUI?.GMMakroButton ||
    !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen ||
    !globalThis.DSK?.GabenUI?.AnfrageKarteAktualisieren;

if (frameworkFehlt) {
    const fwMacro = await fromUuid(frameworkUuid);
    if (!fwMacro?.execute) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
    await fwMacro.execute();
    await new Promise(resolve => setTimeout(resolve, 150));
}

const DSK_FW = globalThis.DSK;
if (
    !DSK_FW?.Effekt?.Anwenden || !DSK_FW?.EffektEnde?.Register ||
    !DSK_FW?.QS?.Ermitteln || !DSK_FW?.Token?.Finde ||
    !DSK_FW?.Target?.Merken || !DSK_FW?.Target?.Finden ||
    !DSK_FW?.Target?.Actor || !DSK_FW?.Wesen?.match ||
    !DSK_FW?.GMAnfrage?.Speichern || !DSK_FW?.GMAnfrage?.Finden ||
    !DSK_FW?.GMAnfrage?.Lesen || !DSK_FW?.GMAnfrage?.Loeschen ||
    !DSK_FW?.GabenUI?.GMMakroButton ||
    !DSK_FW?.GabenUI?.AnfrageKarteErstellen ||
    !DSK_FW?.GabenUI?.AnfrageKarteAktualisieren
) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework 01.02 wurde nicht vollständig geladen!");

// +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++++++
const gabenName = "Nurtis Schmeicheln", vollerName = "Nurtis Schmeicheln (Nurti)", ahne = "Nurti";
const flagKey = "pendingNurtisSchmeichelnNurti", endeKey = "nurtiSchmeicheln";
const endeText = "Der magische Zwang zu streicheln vergeht. Beide sind wieder frei.";

DSK_FW.EffektEnde.Register(endeKey, vollerName, endeText);

// +++ 3 - HELFER ++++++++++++++++++++++++++++++++++++++++++++++
const raeumeQSAuf = async actor => {
    if (actor?.getFlag("world", "letzteGabenQS") !== undefined) await actor.unsetFlag("world", "letzteGabenQS");
    if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) await actor.unsetFlag("world", "letzteGabenMessageId");
};

const istMensch = actor => DSK_FW.Wesen.match(actor, ["mensch", "menschen"]);

const ladeZiel = async daten => {
    if (!daten) return { token: null, actor: null };
    const token = await DSK_FW.Target.Finden(daten);
    return { token, actor: token?.actor || await DSK_FW.Target.Actor(daten) };
};

const findeEigeneEffekte = (actor, casterUuid) =>
    (actor?.effects || []).filter(e =>
        (e.name || e.label || "") === vollerName &&
        e.getFlag("dsk", "isNurtisSchmeicheln") === true &&
        e.getFlag("dsk", "casterUuid") === casterUuid
    );

const beschreibungFuer = (casterName, targetName, qs) => {
    const malus = qs * 2;
    return `<b>${casterName}</b> zwingt <b>${targetName}</b> zu einer ausgedehnten Streicheleinheit.` +
        `<br><br>Der betroffene Mensch muss das Nurtikind für <b>${qs} Minute(n)</b> streicheln.` +
        `<br>Zum vorzeitigen Aufhören ist eine um <b>${malus} erschwerte Willenskraft-Probe</b> nötig.` +
        `<br><br><i>Wird das Nurtikind angegriffen oder muss es um Leib und Leben fürchten, endet der Zwang.</i>` +
        `<br><b>Zielkategorie:</b> Menschen`;
};

// +++ 4 - VERKNÜPFTE EFFEKTE ANWENDEN ++++++++++++++++++++++++
const wendeEffekteAn = async ({ casterActor, targetActor, qs }) => {
    if (!casterActor || !targetActor || !istMensch(targetActor)) return false;

    const casterName = DSK_FW.ResolveTokenName(casterActor) || casterActor.name;
    const targetName = DSK_FW.ResolveTokenName(targetActor) || targetActor.name;
    const malus = qs * 2;

    const zielAlt = findeEigeneEffekte(targetActor, casterActor.uuid);
    const casterAlt = findeEigeneEffekte(casterActor, casterActor.uuid);

    if (zielAlt.length) {
        await targetActor.deleteEmbeddedDocuments("ActiveEffect", zielAlt.map(e => e.id));
    }

    if (casterAlt.length) {
        await casterActor.deleteEmbeddedDocuments("ActiveEffect", casterAlt.map(e => e.id));
    }

    const zielEffekt = await DSK_FW.Effekt.Anwenden({
        name: vollerName,
        ahne,
        beschreibung:
            `<b>${targetName}</b> wird von <b>${casterName}</b> dazu gezwungen, das Nurtikind zu streicheln.` +
            `<br><br><b>Willenskraft:</b> −${malus}` +
            `<br><b>Wirkungsdauer:</b> ${qs} Minute(n)`,
        gabeZiel: "menschen",
        qs,
        ziel: targetActor,
        changes: [{
            key: "system.skillModifiers.FW",
            mode: 0,
            value: `Willenskraft -${malus}`,
            priority: 20
        }],
        duration: { minutes: qs },
        showIcon: 1,
        flags: {
            dsk: {
                isNurtisSchmeicheln: true,
                rolle: "ziel",
                casterUuid: casterActor.uuid,
                linkedActorUuid: casterActor.uuid,
                linkedActorName: casterName,
                qs,
                willenskraftMalus: malus,
                wirkungsende: {
                    sfName: endeKey,
                    basisEffektName: vollerName,
                    beschreibungFuerEnde: endeText
                }
            }
        }
    });

    if (!zielEffekt) return false;

    let casterEffekt = null;

    try {
        casterEffekt = await DSK_FW.Effekt.Anwenden({
            name: vollerName,
            ahne,
            beschreibung:
                `<b>${casterName}</b> lässt sich genüsslich von <b>${targetName}</b> streicheln.` +
                `<br><br>Beide sind an diese Handlung gebunden.` +
                `<br><b>Wirkungsdauer:</b> ${qs} Minute(n)`,
            gabeZiel: "selbst",
            qs,
            ziel: casterActor,
            changes: [],
            duration: { minutes: qs },
            showIcon: 1,
            flags: {
                dsk: {
                    isNurtisSchmeicheln: true,
                    rolle: "wirkender",
                    casterUuid: casterActor.uuid,
                    linkedActorUuid: targetActor.uuid,
                    linkedActorName: targetName,
                    qs,
                    wirkungsende: {
                        sfName: endeKey,
                        basisEffektName: vollerName,
                        beschreibungFuerEnde: endeText
                    }
                }
            }
        });
    } catch (error) {
        console.error("Nurtis Schmeicheln: Effekt auf dem Wirkenden fehlgeschlagen.", error);
    }

    if (!casterEffekt) {
        try {
            await zielEffekt.delete();
        } catch (error) {
            console.error("Nurtis Schmeicheln: Unvollständiger Zieleffekt konnte nicht entfernt werden.", error);
        }
        return false;
    }

    const zielEnde = zielEffekt.getFlag("dsk", "wirkungsende");
    const casterEnde = casterEffekt.getFlag("dsk", "wirkungsende");

    const malusKorrekt = (zielEffekt.changes || []).some(change =>
        change.key === "system.skillModifiers.FW" &&
        Number(change.mode) === 0 &&
        String(change.value) === `Willenskraft -${malus}`
    );

    return Boolean(
        zielEffekt.parent?.uuid === targetActor.uuid &&
        casterEffekt.parent?.uuid === casterActor.uuid &&
        zielEffekt.getFlag("dsk", "rolle") === "ziel" &&
        casterEffekt.getFlag("dsk", "rolle") === "wirkender" &&
        zielEffekt.getFlag("dsk", "linkedActorUuid") === casterActor.uuid &&
        casterEffekt.getFlag("dsk", "linkedActorUuid") === targetActor.uuid &&
        Number(zielEffekt.getFlag("dsk", "willenskraftMalus")) === malus &&
        zielEnde?.sfName === endeKey &&
        casterEnde?.sfName === endeKey &&
        malusKorrekt
    );
};

// +++ 5 - GM-ANFRAGE VERARBEITEN +++++++++++++++++++++++++++++
const verarbeiteAnfrage = async (casterActor, daten) => {
    if (!game.user.isGM || !casterActor || !daten) return false;

    if (daten.casterUuid && daten.casterUuid !== casterActor.uuid) {
        ui.notifications.warn("Luna sagt 🌙: Die gespeicherte Anfrage passt nicht zum Wirkenden.");
        return false;
    }

    if (daten.sceneId && daten.sceneId !== canvas.scene?.id) {
        ui.notifications.warn(`Luna sagt 🌙: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`);
        return false;
    }

    const casterToken = DSK_FW.Token.Finde(casterActor, daten.casterTokenId, daten.casterTokenUuid);
    if (!casterToken) {
        ui.notifications.warn(`Luna sagt 🌙: Der Token von „${casterActor.name}“ wurde nicht gefunden!`);
        return false;
    }

    const { token: targetToken, actor: targetActor } = await ladeZiel(daten.target);
    const qs = Math.max(1, Math.floor(Number(daten.qs) || 1));
    const casterName = daten.casterName || DSK_FW.ResolveTokenName(casterActor);
    const targetName = daten.target?.name || targetToken?.name || targetActor?.name || "Unbekanntes Ziel";
    let erfolgreich = false;

    if (targetActor && istMensch(targetActor)) {
        try {
            erfolgreich = await wendeEffekteAn({ casterActor, targetActor, qs });
        } catch (error) {
            console.error("Nurtis Schmeicheln: Effektanlage fehlgeschlagen.", {
                casterActor, targetActor, daten, error
            });
        }
    }

    await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
        messageId: daten.messageId,
        gabenName: vollerName,
        ahne,
        beschreibung: daten.beschreibung || beschreibungFuer(casterName, targetName, qs),
        wirkender: casterName,
        ziele: erfolgreich ? [{ name: targetName, rolle: "Streichelnder" }] : [],
        misserfolge: erfolgreich ? [] : [{ name: targetName }],
        dauerText: `${qs} Minute(n)`,
        erfolgreich
    });

    if (erfolgreich) {
        ui.notifications.info(
            `Luna sagt 🌙: ${targetName} muss ${casterName} streicheln. Willenskraft −${qs * 2}.`
        );
    } else {
        ui.notifications.error(
            "Luna sagt 🌙: Nurtis Schmeicheln konnte nicht vollständig angewendet werden!"
        );
    }

    return true;
};

// +++ 6 - GM-MODUS ++++++++++++++++++++++++++++++++++++++++++++
if (game.user.isGM) {
    const anfragen = DSK_FW.GMAnfrage.Finden(flagKey);

    if (anfragen.length) {
        for (const anfrageActor of anfragen) {
            const daten = DSK_FW.GMAnfrage.Lesen(anfrageActor, flagKey);
            if (!daten) continue;

            if (await verarbeiteAnfrage(anfrageActor, daten)) {
                await DSK_FW.GMAnfrage.Loeschen(anfrageActor, flagKey);
            }
        }

        return;
    }
}

// +++ 7 - WIRKENDER +++++++++++++++++++++++++++++++++++++++++++
let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;

if (!casterActor) {
    casterActor =
        canvas.tokens.placeables.map(token => token.actor).find(actor =>
            actor?.getFlag("world", "letzteGabenQS") !== undefined
        ) ||
        game.actors.find(actor =>
            actor.getFlag("world", "letzteGabenQS") !== undefined
        ) ||
        null;
}

if (!casterActor) {
    return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");
}

if (!game.user.isGM && !casterActor.isOwner) {
    return ui.notifications.warn(
        "Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!"
    );
}

const casterToken = DSK_FW.Token.Finde(casterActor);
if (!casterToken) {
    return ui.notifications.warn(
        "Luna sagt 🌙: Der Wirkende braucht einen Token auf der aktuellen Szene!"
    );
}

const casterName = DSK_FW.ResolveTokenName(casterActor);

// +++ 8 - QS ++++++++++++++++++++++++++++++++++++++++++++++++++
const qs = DSK_FW.QS.Ermitteln({
    actor: casterActor,
    gabenName,
    suchbegriffe: ["Nurtis Schmeicheln Probe", "Nurtis Schmeicheln"],
    testDataObj: typeof testData !== "undefined" ? testData : null,
    fallback: 0,
    protokollieren: true
});

if (qs <= 0) {
    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName,
        ahne,
        beschreibung: "Der magische Zwang zum Streicheln konnte nicht erzeugt werden.",
        wirkender: casterName,
        ziele: [],
        misserfolge: [{ name: casterName }],
        dauerText: "Keine Wirkung",
        gmBereich: false,
        angewendet: true,
        erfolgreich: false,
        anfragenderUserId: game.user.id
    });

    await raeumeQSAuf(casterActor);
    return;
}

// +++ 9 - GENAU EIN MENSCHLICHES ZIEL +++++++++++++++++++++++++
const targets = Array.from(game.user.targets || []);

if (targets.length !== 1) {
    await raeumeQSAuf(casterActor);
    return ui.notifications.warn(
        "Luna sagt 🌙: Bitte wähle genau einen Menschen als Ziel!"
    );
}

const targetToken = targets[0];
const targetActor = targetToken?.actor;
const targetName = targetToken?.name || targetActor?.name || "Unbekanntes Ziel";

if (!targetActor || !istMensch(targetActor)) {
    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName,
        ahne,
        beschreibung: `<b>${targetName}</b> ist kein Mensch. Diese Gabe wirkt nur bei menschlichen Wesen.`,
        wirkender: casterName,
        ziele: [],
        misserfolge: [{ name: targetName }],
        dauerText: "Keine Wirkung",
        gmBereich: false,
        angewendet: true,
        erfolgreich: false,
        anfragenderUserId: game.user.id
    });

    await raeumeQSAuf(casterActor);
    return;
}

if (targetActor.uuid === casterActor.uuid) {
    await raeumeQSAuf(casterActor);
    return ui.notifications.warn(
        "Luna sagt 🌙: Das Nurtikind kann sich nicht selbst zum Streicheln zwingen!"
    );
}

const targetDaten = DSK_FW.Target.Merken(targetToken);

if (!targetDaten) {
    await raeumeQSAuf(casterActor);
    return ui.notifications.error(
        "Luna sagt 🌙: Das Ziel konnte nicht gespeichert werden!"
    );
}

// +++ 10 - KARTE + GM-BUTTON ++++++++++++++++++++++++++++++++++
const dauerText = `${qs} Minute(n)`;
const beschreibung = beschreibungFuer(casterName, targetName, qs);

const gmLink = DSK_FW.GabenUI.GMMakroButton(
    macroUuid,
    "Effekt anwenden",
    "Das Makro muss durch die Spielleitung ausgeführt werden."
);

const nachricht = await DSK_FW.GabenUI.AnfrageKarteErstellen({
    gabenName: vollerName,
    ahne,
    beschreibung,
    wirkender: casterName,
    ziele: [{ name: targetName, rolle: "Streichelnder" }],
    misserfolge: [],
    dauerText,
    gmLink,
    gmBereich: !game.user.isGM,
    anfragenderUserId: game.user.id
});

if (!nachricht) {
    await raeumeQSAuf(casterActor);
    return ui.notifications.error(
        "Luna sagt 🌙: Die Wirkungskarte konnte nicht erstellt werden!"
    );
}

const anfrageDaten = {
    casterUuid: casterActor.uuid,
    casterName,
    casterTokenId: casterToken.id,
    casterTokenUuid: casterToken.document?.uuid || casterToken.uuid || null,
    target: targetDaten,
    qs,
    beschreibung,
    sceneId: canvas.scene?.id || null,
    requestedByUserId: game.user.id,
    messageId: nachricht.id,
    macroUuid,
    erstellt: Date.now()
};

// +++ 11 - DIREKT ODER GM-ANFRAGE +++++++++++++++++++++++++++++
if (game.user.isGM) {
    await verarbeiteAnfrage(casterActor, anfrageDaten);
    await raeumeQSAuf(casterActor);
    return;
}

await DSK_FW.GMAnfrage.Speichern(casterActor, flagKey, anfrageDaten);
await raeumeQSAuf(casterActor);

ui.notifications.info(
    "Luna sagt 🌙: Nurtis Schmeicheln wurde bei der Spielleitung zur Anwendung beantragt."
);
}).call(this);
